char a [maxn][maxn] ;
int dp [maxn][maxn] ;  
signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    cin >> n ; 
    for ( int i = 1 ; i <= n ; i ++ ) for ( int j = 1 ; j <= n ; j ++ ) cin >> a [i][j] ; 
    dp [1][1] = (a[1][1] == '.') ; 
    for ( int i = 1 ; i <= n ; i ++ ) for ( int j = 1 ; j <= n ; j ++ ) 
    {
        if ( a [i][j] == '*' ) continue ; 
        if ( i > 1 ) add (dp[i][j],dp[i-1][j]) ; 
        if ( j > 1 ) add (dp[i][j],dp[i][j-1]) ; 
    }
    cout << dp [n][n] ; 
    return 0;
}
